// Astro + Starlight configuration of the abfc documentation site.
// The pages under src/content/docs/ (except index.mdx) are generated by `npm run generate` from ../docs/*.md and the node reference data.
import { defineConfig } from "astro/config";
import starlight from "@astrojs/starlight";
import starlightLlmsTxt from "starlight-llms-txt";
import { readFileSync } from "node:fs";
import { BASE, REPO_URL, SITE } from "./site.mjs";
import { modulesOf } from "./lib/nodes.mjs";

const signatures = JSON.parse(readFileSync(new URL("./data/node-signatures.json", import.meta.url), "utf8"));

export default defineConfig({
  site: SITE,
  base: BASE,
  trailingSlash: "always",
  integrations: [
    starlight({
      title: "abfc",
      description: "Write Abiotic Factor Blueprints in TypeScript",
      social: [{ icon: "github", label: "GitHub", href: REPO_URL }],
      customCss: ["./src/styles/custom.css"],
      components: { Search: "./src/components/Search.astro" },
      plugins: [
        starlightLlmsTxt({
          projectName: "abfc",
          description:
            "abfc compiles TypeScript classes into Abiotic Factor Blueprints and publishes them to your mod through the official Mod Editor.",
          exclude: ["404"],
          optionalLinks: [
            {
              label: "Node reference, one line per function",
              url: `${SITE}${BASE}/llms-nodes.txt`,
              description: "every engine and game-module function with its Blueprint node name, TypeScript name and signature",
            },
          ],
        }),
      ],
      sidebar: [
        { label: "Start here", items: ["getting-started", "guides/install", "guides/first-mod"] },
        { label: "Guides", items: ["guides/troubleshooting"] },
        {
          label: "Reference",
          items: [
            "reference/runtime",
            "reference/cli",
            "reference/config",
            "reference/errors",
            "reference/lint-rules",
            "reference/language-service",
            "reference/backend",
          ],
        },
        {
          label: "Node reference",
          collapsed: true,
          items: [
            "reference/nodes",
            ...modulesOf(signatures).map((m) => ({ label: `${m.name} (${m.count})`, link: `/${m.slug}/` })),
          ],
        },
      ],
    }),
  ],
});
